PARAMS = ['R0','kout','Imax','IC50','ke0']
def predict(df, p):
    def solve_one(dose, ts):
        ts = np.asarray(ts, float)
        def rhs(t, y):
            C = pk_conc(dose, np.array([t]))[0]
            Ce, R = y
            dCe = p['ke0']*(C - Ce)
            dR = p['kout']*p['R0']*(1 - p['Imax']*Ce/(p['IC50']+Ce)) - p['kout']*R
            return [dCe, dR]
        sol = solve_ivp(rhs, [0, ts.max()], [0.0, p['R0']], t_eval=ts, rtol=1e-8, atol=1e-10)
        return sol.y[1]
    return per_dose(df, solve_one)

